#else
#define debug(...)
#define debugArr(...)
#endif

const int maxn = 1e6 + 5;

int n, m, s;

int head[maxn], to[maxn], wt[maxn], nxt[maxn], ecnt;
int dhead[maxn], dto[maxn], dwt[maxn], dnxt[maxn], dcnt;

int num[maxn], low[maxn], scc[maxn];
bool instk[maxn];
int stk[maxn], top;
int timer, comp;

long long scc_w[maxn];
long long dp[maxn];

void add(int u, int v, int w) {
    ++ecnt;
    to[ecnt] = v;
    wt[ecnt] = w;
    nxt[ecnt] = head[u];
    head[u] = ecnt;
}

void addcomp(int u, int v, int w) {
    ++dcnt;
    dto[dcnt] = v;
    dwt[dcnt] = w;
    dnxt[dcnt] = dhead[u];
    dhead[u] = dcnt;
}

long long calc(long long w) {
    if (w <= 0) return 0;
    long long k = (1 + sqrt(1.0 + 8.0 * w)) / 2;
    while (k * (k - 1) / 2 > w) --k;
    while ((k + 1) * k / 2 <= w) ++k;
    return k * w - (k - 1) * k * (k + 1) / 6;
}

void tarjan(int u) {
    num[u] = low[u] = ++timer;
    stk[++top] = u;
    instk[u] = true;

    for (int i = head[u]; i; i = nxt[i]) {
        int v = to[i];
        if (!num[v]) {
            tarjan(v);
            low[u] = min(low[u], low[v]);
        } else if (instk[v]) {
            low[u] = min(low[u], num[v]);
        }
    }

    if (low[u] == num[u]) {
        ++comp;
        while (1) {
            int v = stk[top--];
            instk[v] = false;
            scc[v] = comp;
            if (v == u) break;
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    cin >> n >> m;

    for (int i = 1; i <= m; i++) {
        int u, v, w;
        cin >> u >> v >> w;
        add(u, v, w);
    }

    cin >> s;

    for (int i = 1; i <= n; i++)
        if (!num[i])
            tarjan(i);

    for (int u = 1; u <= n; u++) {
        for (int i = head[u]; i; i = nxt[i]) {
            int v = to[i];
            if (scc[u] == scc[v])
                scc_w[scc[u]] += calc(wt[i]);
            else
                addcomp(scc[u], scc[v], wt[i]);
        }
    }

    for (int i = 1; i <= comp; i++)
        dp[i] = -1;

    dp[scc[s]] = scc_w[scc[s]];

    long long ans = 0;

    for (int u = comp; u >= 1; u--) {
        if (dp[u] == -1) continue;
        ans = max(ans, dp[u]);

        for (int i = dhead[u]; i; i = dnxt[i]) {
            int v = dto[i];
            dp[v] = max(dp[v], dp[u] + dwt[i] + scc_w[v]);
        }
    }

    cout << ans << '\n';
}